/**
 * Concatenates the relational migrations into one file to paste into the
 * Supabase SQL Editor, since there is no linked CLI / local Docker here.
 *
 * Usage: node scripts/build-sql-bundle.mjs
 */

import { readFileSync, writeFileSync, mkdirSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const all = [
  "20260821120000_relational_schema.sql",
  "20260821121000_app_data_functions.sql",
  "20260821130000_nullable_unassigned_physio.sql",
  "20260821131000_seed_masseur.sql",
  "20260821140000_relax_required_strings.sql",
];

// Named subsets let a fix be pasted without re-running the whole schema.
const subsets = {
  functions: ["20260821121000_app_data_functions.sql"],
  patch: [
    "20260821130000_nullable_unassigned_physio.sql",
    "20260821121000_app_data_functions.sql",
  ],
  patch2: [
    "20260821140000_relax_required_strings.sql",
    "20260821121000_app_data_functions.sql",
  ],
};

const mode = process.argv[2];
const migrations = subsets[mode] ?? all;

const parts = migrations.map((name) => {
  const body = readFileSync(join(root, "supabase", "migrations", name), "utf8").trim();
  return `-- ===========================================================================\n-- ${name}\n-- ===========================================================================\n\n${body}`;
});

const sql = `-- Generated by scripts/build-sql-bundle.mjs — do not edit by hand.\n-- Paste the whole file into the Supabase SQL Editor and run once.\n-- Safe to re-run: every statement is create-if-not-exists or create-or-replace.\n\nbegin;\n\n${parts.join("\n\n")}\n\ncommit;\n`;

const outDir = join(root, "supabase", "bundle");
mkdirSync(outDir, { recursive: true });
const outPath = join(outDir, mode ? `${mode}.sql` : "relational-migration.sql");
writeFileSync(outPath, sql, "utf8");

console.log(`Written: ${outPath}`);
console.log(`Bytes:   ${Buffer.byteLength(sql, "utf8")}`);
